inline Option::Option(double S_, double K_, double T_, double vol_, double r_, bool is_call_)
    : S(S_), K(K_), T(T_), vol(vol_), r(r_), is_call(is_call_) {
    // __post_init__
    if (S <= 0 || K <= 0 || T <= 0 || vol <= 0) {
        throw std::invalid_argument("S, K, T and vol must be positive");
    }
}

inline double Option::forward() const {
    return S * std::exp(r * T);
}

inline double Option::d1() const {
    return (std::log(forward() / K) + 0.5 * (vol * vol) * T) / (vol * std::sqrt(T));
}

inline double Option::price() const {
    double d1_ = d1();
    double d2 = d1_ - vol * std::sqrt(T);
    double df = std::exp(-r * T);
    if (is_call) {
        return df * (forward() * qt::norm_cdf(d1_) - K * qt::norm_cdf(d2));
    }
    return df * (K * qt::norm_cdf(-d2) - forward() * qt::norm_cdf(-d1_));
}

inline double Option::delta() const {
    double n = qt::norm_cdf(d1());
    return is_call ? n : n - 1.0;
}

inline Option Option::atm(double S_, double T_, double vol_, double r_) {
    return Option(S_, S_ * std::exp(r_ * T_), T_, vol_, r_);
}

inline bool Option::operator==(const Option& other) const {
    return S == other.S && K == other.K && T == other.T && vol == other.vol && r == other.r && is_call == other.is_call;
}

inline Quote::Quote(double bid_, double ask_)
    : bid(bid_), ask(ask_) {}

inline double Quote::mid() const {
    return 0.5 * (bid + ask);
}

inline double Quote::spread_bps() const {
    return 10000.0 * (ask - bid) / mid();
}

inline bool Quote::operator==(const Quote& other) const {
    return bid == other.bid && ask == other.ask;
}

inline Curve::Curve(qt::Vec times_, qt::Vec rates_)
    : times(std::move(times_)), rates(std::move(rates_)) {
    // __post_init__
    if (times.size() != rates.size()) {
        throw std::invalid_argument("times and rates differ in length");
    }
    if (times.size() == 0) {
        throw std::invalid_argument("empty curve");
    }
}

inline double Curve::zero(double t) const {
    qt::Vec ts = times;
    qt::Vec rs = rates;
    if (t <= ts(0)) {
        return rs(0);
    }
    if (t >= ts(ts.size() - 1)) {
        return rs(rs.size() - 1);
    }
    for (long long i = 1, i_end = ts.size(); i < i_end; ++i) {
        if (t <= ts(i)) {
            double w = (t - ts(i - 1)) / (ts(i) - ts(i - 1));
            return rs(i - 1) + w * (rs(i) - rs(i - 1));
        }
    }
    return rs(rs.size() - 1);
}

inline double Curve::df(double t) const {
    return std::exp(-zero(t) * t);
}

inline Bond::Bond(double face_, double coupon_, double maturity_, long long freq_)
    : face(face_), coupon(coupon_), maturity(maturity_), freq(freq_), n_periods(0) {
    // __post_init__
    if (freq <= 0 || maturity <= 0 || maturity > 100) {
        throw std::invalid_argument("freq and maturity must be positive, maturity at most 100 years");
    }
    n_periods = qt::to_int(std::nearbyint(maturity * static_cast<double>(freq)));
}

inline double Bond::price(const Curve& curve) const {
    double c = face * coupon / static_cast<double>(freq);
    double pv = 0.0;
    for (long long k = 1; k < qt::iadd(n_periods, 1LL); ++k) {
        pv += c * curve.df(static_cast<double>(k) / static_cast<double>(freq));
    }
    return pv + face * curve.df(static_cast<double>(n_periods) / static_cast<double>(freq));
}

inline bool Bond::operator==(const Bond& other) const {
    return face == other.face && coupon == other.coupon && maturity == other.maturity && freq == other.freq && n_periods == other.n_periods;
}

inline Portfolio::Portfolio(qt::Vec weights_, double cash_)
    : weights(std::move(weights_)), cash(cash_), trades(0) {}

inline double Portfolio::value(const qt::Vec& prices) const {
    return qt::dot(weights, prices) + cash;
}

/// Move to the target weights, paying cost_bps on the turnover out of cash.
inline double Portfolio::rebalance(const qt::Vec& target, const qt::Vec& prices, double cost_bps) {
    double turnover = qt::sum(qt::broadcast(target, weights, qt::sub_op{}).abs());
    double cost = turnover * cost_bps * 0.0001 * value(prices);
    weights = target;
    cash -= cost;
    trades = qt::iadd(trades, 1LL);
    return cost;
}

inline void Portfolio::scale(double k) {
    weights *= k;
}

inline Account::Account(Portfolio port_, std::string name_, std::string stance_)
    : port(std::move(port_)), name(std::move(name_)), stance(std::move(stance_)) {}

inline double Account::nav(const qt::Vec& prices) const {
    return port.value(prices);
}

inline GBMEngine::GBMEngine(double s0_, double r_, double sigma_, long long seed, long long steps_per_year) {
    // __init__
    if (s0_ <= 0 || sigma_ < 0 || steps_per_year <= 0) {
        throw std::invalid_argument("need s0 > 0, sigma >= 0, steps_per_year > 0");
    }
    s0 = s0_;
    r = r_;
    sigma = sigma_;
    dt = 1.0 / static_cast<double>(steps_per_year);
    rng = qt::Rng(seed);
    paths_run = 0;
}

inline qt::Vec GBMEngine::terminal(long long n_paths, double years) {
    if (years <= 0 || years > 10 || n_paths < 1 || n_paths > 100000) {
        throw std::invalid_argument("need 0 < years <= 10 and 1 <= n_paths <= 100000");
    }
    long long steps = std::max(1LL, qt::to_int(std::nearbyint(years / dt)));
    double h = years / static_cast<double>(steps);
    double drift = (r - 0.5 * (sigma * sigma)) * h;
    double vol = sigma * std::sqrt(h);
    qt::Vec logs = qt::zeros(n_paths);
    for (long long _ = 0; _ < steps; ++_) {
        qt::Vec z = rng.standard_normal(n_paths);
        logs += drift + vol * z;
    }
    paths_run = qt::iadd(paths_run, n_paths);
    return s0 * qt::exp(logs);
}

inline double GBMEngine::call(double K, double years, long long n_paths) {
    qt::Vec st = terminal(n_paths, years);
    return std::exp(-r * years) * qt::mean(qt::maximum(st - K, 0.0));
}

/// A Monte Carlo call price next to the closed form, and how many paths the engine ran.
inline std::tuple<double, double, long long> mc_vs_black_scholes(long long seed, double K, double years) {
    GBMEngine eng = GBMEngine(100.0, 0.04, 0.2, seed, 52);
    double mc = eng.call(K, years, 4000);
    double exact = Option(100.0, K, years, 0.2, 0.04).price();
    return {mc, exact, eng.paths_run};
}

/// Draws from the caller's engine: its generator moves on, as in Python.
inline double reprice(GBMEngine& eng, double K) {
    return eng.call(K, 0.25, 2000);
}

/// The box each weight must stay in, for a portfolio stance.
inline std::tuple<double, double> weight_bounds(const std::string& stance, double cap) {
    if (stance == "Long only") {
        return {0.0, cap};
    }
    if (stance == "Short only") {
        return {-cap, 0.0};
    }
    if (stance == "Long-short" || stance == "Market neutral") {
        return {-cap, cap};
    }
    throw std::invalid_argument("unknown stance");
}

inline double book_value(const Option& options, double qty) {
    return qty * options.price();
}

/// Central-difference delta by repricing bumped copies: should match o.delta().
inline double bumped_delta(const Option& o, double h) {
    Option up = Option(o.S + h, o.K, o.T, o.vol, o.r, o.is_call);
    Option dn = Option(o.S - h, o.K, o.T, o.vol, o.r, o.is_call);
    return (up.price() - dn.price()) / (2.0 * h);
}

inline double straddle(double S, double T, double vol, double r) {
    Option c = Option::atm(S, T, vol, r);
    Option p = Option(c.S, c.K, c.T, c.vol, c.r, false);
    return c.price() + p.price();
}

inline std::tuple<double, double, double> quote_stats(const Quote& q) {
    auto [bid, ask] = q;
    return {q.mid(), q.spread_bps(), ask - bid};
}

inline double bond_price(const Bond& b, const Curve& curve) {
    return b.price(curve);
}

inline Curve parallel_shift(const Curve& curve, double h) {
    return Curve(curve.times, curve.rates + h);
}

inline double dv01(const Bond& b, const Curve& curve) {
    return (b.price(parallel_shift(curve, -0.0001)) - b.price(parallel_shift(curve, 0.0001))) / 2.0;
}

inline double run_rebalances(Portfolio& p, const qt::Vec& target, const qt::Vec& prices, long long n) {
    double total = 0.0;
    for (long long _ = 0; _ < n; ++_) {
        total += p.rebalance(target, prices, 5.0);
    }
    return total;
}

inline Portfolio scaled_copy(const Portfolio& p, double k) {
    Portfolio q = Portfolio(p);
    q.scale(k);
    return q;
}

inline double leveraged_nav(const Account& acc, const qt::Vec& prices, double k) {
    auto [lo, hi] = weight_bounds(acc.stance, 1.0);
    Account a = Account(acc);
    a.port.scale(k);
    a.port.weights = (qt::clip(a.port.weights, lo, hi)).eval();
    return a.nav(prices);
}

